export function buildSeedVips(now: number): Vip[] {
  return DEFS.map((d) => {
    const { history, totalVolume } = genHistory(
      d.curve,
      d.sharesOutstanding,
      d.rngSeed,
      now
    );
    const fees = totalVolume * FEE_RATE;
    return {
      id: d.slug,
      slug: d.slug,
      name: d.name,
      category: d.category,
      tagline: d.tagline,
      bio: d.bio,
      initials: d.initials,
      hue: d.hue,
      indexScore: d.indexScore,
      indexSignals: d.indexSignals,
      curve: d.curve,
      sharesOutstanding: d.sharesOutstanding,
      supplySoftCap: d.supplySoftCap,
      reserve: reserveAt(d.curve, d.sharesOutstanding),
      totalVolume,
      vipFeesAccrued: fees * VIP_FEE_SHARE,
      platformFeesAccrued: fees * (1 - VIP_FEE_SHARE),
      priceHistory: history,
      updates: d.updates.map((u, i) => ({
        id: `${d.slug}-u${i}`,
        ts: now - u.daysAgo * DAY,
        body: u.body,
      })),
      licenseExecutedAt: d.licenseExecutedAt,
    };
  });
}
